windowclass.script:
function onInit()
	if super and super.onInit then
		super.onInit();
	end
	if temphp then
		temphp.setColor(ColorManager.COLOR_TEMP_HP);
	elseif hptemp then
		hptemp.setColor(ColorManager.COLOR_TEMP_HP);
	end
	if wounded then
		wounded.setColor(ColorManager.COLOR_HEALTH_HVY_WOUNDS);
	end
	if dying then
		dying.setColor(ColorManager.COLOR_HEALTH_CRIT_WOUNDS);
	end
end

function onInit()
	if super and super.onInit then
		super.onInit();
	end
	if temphp then
		temphp.setColor(ColorManager.COLOR_TEMP_HP);
	elseif hptemp then
		hptemp.setColor(ColorManager.COLOR_TEMP_HP);
	end
	if wounded then
		wounded.setColor(ColorManager.COLOR_HEALTH_HVY_WOUNDS);
	end
	if dying then
		dying.setColor(ColorManager.COLOR_HEALTH_CRIT_WOUNDS);
	end
end

function onInit()
	if super and super.onInit then
		super.onInit();
	end
	recolorSectionLabel();
end
function updatePreparedTactics()
	if super and super.updatePreparedTactics then
		super.updatePreparedTactics();
	end
	recolorSectionLabel();
end
function recolorSectionLabel()
	if not activitysections then
		return;
	end
	local tSections = activitysections.getWindows();
	if tSections and tSections[1] and tSections[1].label then
		local sVal = tSections[1].label.getValue() or "";
		if sVal:find("Too Many", 1, true) then
			tSections[1].label.setColor("#FF6161");
		else
			tSections[1].label.setColor("#FFF0CA");
		end
	end
end

function onInit()
	if super and super.onInit then
		super.onInit();
	end
	recolorSectionLabel();
end
function updatePreparedRunes()
	if super and super.updatePreparedRunes then
		super.updatePreparedRunes();
	end
	recolorSectionLabel();
end
function recolorSectionLabel()
	if not activitysections then
		return;
	end
	local tSections = activitysections.getWindows();
	if tSections and tSections[1] and tSections[1].label then
		local sVal = tSections[1].label.getValue() or "";
		if sVal:find("Too Many", 1, true) then
			tSections[1].label.setColor("#FF6161");
		else
			tSections[1].label.setColor("#FFF0CA");
		end
	end
end
